async function resolveEntry(event){event.preventDefault();const form=event.target,status=el('taxStatus');if(recoveryState.state!=='complete'){status.textContent='Ledger recovery must verify durable storage before a record can be corrected.';return;}const rootId=form.dataset.rootId,book=readBooks(),root=book.entries.find(row=>row.entry_id===rootId&&!row.correction_of),current=selectedRows().find(row=>row.root_entry_id===rootId);if(!root||!current){status.textContent='That original record could not be found.';return;}if(!resolutionReady(form)){status.textContent='Complete all three steps: choose the payment method, add its safe reference, and mark it Ready or Approved.';syncResolutionForm(form);return;}const data=new FormData(form),next={...current,amount:Number(data.get('amount')),counterparty:String(data.get('counterparty')||'').trim(),description:String(data.get('description')||'').trim(),payment_method:String(data.get('payment_method')||'unspecified'),evidence_ref:String(data.get('evidence_ref')||'').trim(),review_status:String(data.get('review_status')||'unreviewed')},changed=Number(next.amount)!==Number(current.amount)||next.counterparty!==String(current.counterparty||'')||next.description!==String(current.description||''),reason=String(data.get('correction_reason')||'').trim();if(!Number.isFinite(next.amount)||next.amount<=0||!next.description){status.textContent='A corrected record still needs a positive amount and purpose.';return;}if(changed&&!reason){status.textContent='Add a reason before changing the amount, counterparty, or purpose.';return;}const correction={...current,...next,entry_id:uid(),submission_id:uid(),record_kind:'correction',correction_of:rootId,correction_reason:reason||'Attention item resolved',created_at:new Date().toISOString()};delete correction.root_entry_id;delete correction.current_revision_id;delete correction.revision_count;book.entries.push(correction);try{const button=form.querySelector('button[type="submit"]');button.disabled=true;button.querySelector('span').textContent='VERIFYING SAVE…';await writeBooks(book);if(readBooks().entries.filter(row=>row.entry_id===correction.entry_id&&row.correction_of===rootId).length!==1)throw new Error('Resolution read-back did not verify exactly one correction.');const remaining=selectedRows().filter(row=>attentionReasons(row).length).length;status.textContent=remaining?`Saved. ${current.description} is complete. The next record is ready.`:`Saved. ${current.description} is complete. This book has no records waiting for attention.`;status.classList.add('is-success');renderTax();requestAnimationFrame(()=>el('taxCheckQueue')?.scrollIntoView({block:'start',behavior:'smooth'}));}catch(error){status.classList.remove('is-success');status.textContent=`Not saved. ${String(error?.message||error)}`;syncResolutionForm(form);}}
function csvCell(value){const text=String(value??'');return /[",\r\n]/.test(text)?`"${text.replaceAll('"','""')}"`:text;}
function exportCsv(){const rows=selectedRows(),headers=['entity_key','entity_name','entity_type','tax_year','accounting_method','transaction_date','entry_type','category_code','category_label','amount_usd','counterparty','description','payment_method','payment_reference','review_status','acting_office','source','created_at','root_entry_id','current_revision_id','revision_count'],method=el('taxMethod').value,year=el('taxYear').value,csv=[headers.join(','),...rows.map(row=>[row.entity_key,row.entity_name,row.entity_type,year,method,row.transaction_date,row.entry_type,row.category_code,row.category_label,Number(row.amount).toFixed(2),row.counterparty,row.description,row.payment_method||'unspecified',row.evidence_ref,row.review_status,row.acting_office,row.source,row.created_at,row.root_entry_id,row.current_revision_id,row.revision_count].map(csvCell).join(','))].join('\r\n'),blob=new Blob([`\uFEFF${csv}`],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a'),entity=entities().find(row=>row.key===el('taxEntity').value);a.href=url;a.download=`${String(entity?.name||'fleet-book').toLowerCase().replace(/[^a-z0-9]+/g,'-')}-${year}-accountant-ledger.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);el('taxStatus').textContent=`Exported ${rows.length} current transaction${rows.length===1?'':'s'} with correction lineage for ${entity?.name||'this entity'} (${year}).`;}
function setView(next){view=next;document.querySelectorAll('[data-ledger-view]').forEach(button=>{const selected=button.dataset.ledgerView===next;button.classList.toggle('is-selected',selected);button.setAttribute('aria-pressed',String(selected));});el('authorityAuditPanel').classList.toggle('hidden',next!=='audit');el('taxBooksPanel').classList.toggle('hidden',next!=='tax');if(next==='tax'){populateEntities();syncMethod();el('taxOffice').value=office==='admiral'?'admiral':'captain';renderTax();}}
async function open(nextOffice='captain'){office=nextOffice;view='audit';search='';visible=PAGE;el('authorityLedgerSearch').value='';el('authorityLedger').classList.remove('hidden');el('authorityLedger').setAttribute('aria-hidden','false');document.body.classList.add('authority-ledger-open');document.querySelectorAll('[data-ledger-office]').forEach(button=>{const selected=button.dataset.ledgerOffice===office;button.classList.toggle('is-selected',selected);button.setAttribute('aria-pressed',String(selected));});setView('audit');await refresh();}
function close(){el('authorityLedger').classList.add('hidden');el('authorityLedger').setAttribute('aria-hidden','true');document.body.classList.remove('authority-ledger-open');}

document.addEventListener('click',event=>{if(event.target.closest('#captainAuthorityLedgerOpen')){open('captain');return;}if(event.target.closest('#admiralAuthorityLedgerOpen')){open('admiral');return;}if(event.target.closest('#authorityLedgerClose')){close();return;}if(event.target.closest('#taxSave')&&Date.now()-lastSavedAt<2200&&lastSavedEntryId&&!el('taxAmount').value&&!el('taxDescription').value){event.preventDefault();const status=el('taxStatus');status.textContent='Already saved once. No duplicate was created.';status.classList.add('is-success');return;}if(event.target.closest('#taxToCheck')){checkQueueOpen=!checkQueueOpen;renderTax();return;}if(event.target.closest('#taxCheckClose')){checkQueueOpen=false;renderTax();return;}const targetView=event.target.closest('[data-ledger-view]');if(targetView){setView(targetView.dataset.ledgerView);return;}const targetOffice=event.target.closest('[data-ledger-office]');if(targetOffice){office=targetOffice.dataset.ledgerOffice;visible=PAGE;document.querySelectorAll('[data-ledger-office]').forEach(button=>{const selected=button===targetOffice;button.classList.toggle('is-selected',selected);button.setAttribute('aria-pressed',String(selected));});refresh();return;}const targetFlow=event.target.closest('[data-tax-flow]');if(targetFlow){setTaxFlow(targetFlow.dataset.taxFlow);return;}if(event.target.closest('#authorityLedgerRefresh'))refresh();if(event.target.closest('#authorityLedgerMore')){visible+=PAGE;renderAudit();}if(event.target.closest('#taxExportCsv'))exportCsv();});
document.addEventListener('input',event=>{if(event.target.matches('#authorityLedgerSearch')){search=event.target.value;visible=PAGE;renderAudit();}const form=event.target.closest('.tax-resolve-form');if(form)syncResolutionForm(form);});
document.addEventListener('change',async event=>{const resolutionForm=event.target.closest('.tax-resolve-form');if(resolutionForm)syncResolutionForm(resolutionForm);if(event.target.matches('#taxEntity,#taxYear')){syncMethod();renderTax();}if(event.target.matches('#taxMethod')){const book=readBooks(),status=el('taxStatus');book.methods[el('taxEntity').value]=event.target.value;try{await writeBooks(book);renderTax();status.textContent='Accounting method saved for this book.';status.classList.add('is-success');}catch(error){status.textContent=`Not saved. ${String(error?.message||error)}`;}}if(event.target.matches('#taxType')){taxFlow=['income','expense','transfer'].includes(event.target.value)?event.target.value:'transfer';document.querySelectorAll('[data-tax-flow]').forEach(button=>{const selected=button.dataset.taxFlow===taxFlow;button.classList.toggle('is-selected',selected);button.setAttribute('aria-pressed',String(selected));});el('taxSave').textContent=taxFlow==='income'?'SAVE MONEY IN':taxFlow==='expense'?'SAVE MONEY OUT':'SAVE MONEY MOVE';}});
document.addEventListener('submit',event=>{if(event.target.matches('#taxEntryForm'))void appendEntry(event);if(event.target.matches('.tax-resolve-form'))void resolveEntry(event);});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!el('authorityLedger')?.classList.contains('hidden'))close();});
const observer=new MutationObserver(()=>{installCommissioningChoices();enhanceLaunchButtons();});observer.observe(document.documentElement,{childList:true,subtree:true});
window.addEventListener('pageshow',()=>{checkQueueOpen=false;saveInFlight=false;submissionId=uid();document.querySelectorAll('#taxBooksPanel details').forEach(node=>node.open=false);renderTax();});
install();installCommissioningChoices();window.DarkSkyOpenAuthorityLedger=open;window.DarkSkyLedgerIntegrity={build:BUILD,entities,exportSelectedCsv:exportCsv,recoveryStatus:()=>({...recoveryState}),recoveryProof:()=>bookProof(readBooks())};
